DELIMITER $$
--
-- Thủ tục
--
CREATE DEFINER=`root`@`%` PROCEDURE `gen_customer_2026_real` ()   BEGIN
    DECLARE m INT DEFAULT 1;
    DECLARE i INT;
    DECLARE limit_m INT;
    DECLARE base_id INT;

    SET base_id = (SELECT IFNULL(MAX(id),0) FROM customer);

    WHILE m <= 12 DO

            CASE m
                WHEN 1 THEN SET limit_m = 140;
                WHEN 2 THEN SET limit_m = 60;
                WHEN 3 THEN SET limit_m = 90;
                WHEN 4 THEN SET limit_m = 110;
                WHEN 5 THEN SET limit_m = 120;
                WHEN 6 THEN SET limit_m = 160;
                WHEN 7 THEN SET limit_m = 120;
                WHEN 8 THEN SET limit_m = 90;
                WHEN 9 THEN SET limit_m = 100;
                WHEN 10 THEN SET limit_m = 130;
                WHEN 11 THEN SET limit_m = 160;
                WHEN 12 THEN SET limit_m = 180;
                END CASE;

            SET i = 1;
            WHILE i <= limit_m DO
                    SET base_id = base_id + 1;

                        id, name, gender, age,
                        address, phone, email,
                        birthday, height, weight,
                        user_id, creator_id,
                        created_time, updated_time, latest_contact,
                        source_id
                    )
                    SELECT
                        base_id,
                        name,
                        IF(name LIKE '%Thị%',1,2),
                        FLOOR(18 + RAND()*30),
                        CONCAT('Quận ', FLOOR(1+RAND()*12), ', TP.HCM'),
                        CONCAT('09', FLOOR(10000000 + RAND()*89999999)),
                        CONCAT('user', base_id, '@gmail.com'),
                        DATE_SUB(
                                DATE(CONCAT(2026,'-',LPAD(m,2,'0'),'-15')),
                                INTERVAL FLOOR(18+RAND()*30) YEAR
                        ),
                        FLOOR(150 + RAND()*30),
                        FLOOR(45 + RAND()*30),
                        FLOOR(1 + RAND()*3),
                        1,
                        DATE_ADD(
                                DATE(CONCAT(2026,'-',LPAD(m,2,'0'),'-01')),
                                INTERVAL FLOOR(RAND()*27) DAY
                        ),
                        NOW(),
                        DATE_ADD(
                                DATE(CONCAT(2026,'-',LPAD(m,2,'0'),'-01')),
                                INTERVAL FLOOR(RAND()*27) DAY
                        ),
                        FLOOR(1 + RAND()*5)
                    FROM vn_name
                    ORDER BY RAND()
                    LIMIT 1;

                    SET i = i + 1;
                END WHILE;

            SET m = m + 1;
        END WHILE;
END$$

DELIMITER ;

